pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {AirDropContract} from "../src/AirDropContract.sol";

contract InvMutTest is Test {
    AirDropContract c;
    function setUp() public { c = new AirDropContract(); }
    function testRegression_property() public {
        RevertOnTransferFrom helper = new RevertOnTransferFrom();
        address addr = address(helper);
        address[] memory tos = new address[](1);
        tos[0] = address(0x123);
        uint[] memory vs = new uint[](1);
        vs[0] = 0;
        bool ok;
        try c.transfer(addr, tos, vs) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

contract RevertOnTransferFrom {
    fallback(bytes calldata data) external returns (bytes memory) {
        if (bytes4(data[0:4]) == bytes4(0x23b872dd)) {
            revert("transferFrom not supported");
        }
        return "";
    }
}
